insert into public.contenido (codigo, texto, campo_codigo, fase_codigo, fuente_dof_pagina, catalogo_version, requiere_revision_humana) values
  ('CONT-F2-LNG-001', 'Comunicación oral de necesidades, emociones, gustos, ideas y saberes, a través de los diversos lenguajes, desde una perspectiva comunitaria.', 'LENGUAJES', 'FASE_2', 20, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-002', 'Narración de historias mediante diversos lenguajes, en un ambiente donde niñas y niños participen y se apropien de la cultura, a través de diferentes textos.', 'LENGUAJES', 'FASE_2', 20, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-003', 'Recursos y juegos del lenguaje que fortalecen la diversidad de formas de expresión oral, y que rescatan la o las lenguas de la comunidad y de otros lugares.', 'LENGUAJES', 'FASE_2', 21, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-004', 'Reconocimiento y aprecio de la diversidad lingüística, al identificar las formas en que se comunican las distintas personas de la comunidad.', 'LENGUAJES', 'FASE_2', 22, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-005', 'Representación gráfica de ideas y descubrimientos, al explorar los diversos textos que hay en su comunidad y otros lugares.', 'LENGUAJES', 'FASE_2', 22, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-006', 'Expresión de emociones y experiencias, en igualdad de oportunidades, apoyándose de recursos gráficos personales y de los lenguajes artísticos.', 'LENGUAJES', 'FASE_2', 23, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-007', 'Producciones gráficas dirigidas a diversas destinatarias y diversos destinatarios, para establecer vínculos sociales y acercarse a la cultura escrita.', 'LENGUAJES', 'FASE_2', 24, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-008', 'Reconocimiento de ideas o emociones en la interacción con manifestaciones culturales y artísticas y con la naturaleza, a través de diversos lenguajes.', 'LENGUAJES', 'FASE_2', 24, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-LNG-009', 'Producción de expresiones creativas con los distintos elementos de los lenguajes artísticos.', 'LENGUAJES', 'FASE_2', 26, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-001', 'Exploración de la diversidad natural que existe en la comunidad y en otros lugares.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 32, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-002', 'Saberes familiares y comunitarios que resuelven situaciones y necesidades en el hogar y la comunidad.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 33, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-003', 'Los seres vivos: elementos, procesos y fenómenos naturales que ofrecen oportunidades para entender y explicar hechos cotidianos, desde distintas perspectivas.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 33, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-004', 'Los saberes numéricos como herramienta para resolver situaciones del entorno, en diversos contextos socioculturales.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 34, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-005', 'El dominio del espacio y reconocimiento de formas en el entorno desde diversos puntos de observación y mediante desplazamientos o recorridos.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 36, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-006', 'Las magnitudes de longitud, peso, capacidad y tiempo en situaciones cotidianas del hogar y del entorno sociocultural.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 37, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-007', 'Clasificación y experimentación con objetos y elementos del entorno que reflejan la diversidad de la comunidad o región.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 39, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-008', 'Características de objetos y comportamiento de los materiales del entorno sociocultural.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 40, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-SPC-009', 'Objetos y artefactos tecnológicos que mejoran y facilitan la vida familiar y de la comunidad.', 'SABERES_PENSAMIENTO_CIENTIFICO', 'FASE_2', 41, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-001', 'Interacción, cuidado, conservación y regeneración de la naturaleza, que favorece la construcción de una conciencia socioambiental.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 46, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-002', 'Transformación responsable del entorno al satisfacer necesidades básicas de alimentación, vestido y vivienda.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 46, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-003', 'Construcción de la identidad y pertenencia a una comunidad y país a partir del conocimiento de su historia, sus celebraciones, conmemoraciones tradicionales y obras del patrimonio artístico y cultural.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 48, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-004', 'Cambios que ocurren en los lugares, entornos, objetos, costumbres y formas de vida de las distintas familias y comunidades con el paso del tiempo.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 49, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-005', 'Labores y servicios que contribuyen al bien común de las distintas familias y comunidades.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 49, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-006', 'Los derechos de niñas y niños como base para el bienestar integral y el establecimiento de acuerdos que favorecen la convivencia pacífica.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 50, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-007', 'La diversidad de personas y familias en la comunidad y su convivencia, en un ambiente de equidad, libertad, inclusión y respeto a los derechos humanos.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 51, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-ENS-008', 'La cultura de paz como una forma de relacionarse con otras personas para promover la inclusión y el respeto a la diversidad.', 'ETICA_NATURALEZA_SOCIEDADES', 'FASE_2', 51, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-001', 'Construcción de la identidad personal a partir de su pertenencia a un territorio, su origen étnico, cultural y lingüístico, y la interacción con personas cercanas.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 56, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-002', 'Posibilidades de movimiento en diferentes espacios, para favorecer las habilidades motrices.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 56, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-003', 'Precisión y coordinación en los movimientos al usar objetos, herramientas y materiales, de acuerdo con sus condiciones, capacidades y características.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 57, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-004', 'Las emociones en la interacción con diversas personas y situaciones.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 58, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-005', 'Interacción con personas de diversos contextos, que contribuyan al establecimiento de relaciones positivas y a una convivencia basada en la aceptación de la diversidad.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 59, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-006', 'Cuidado de la salud personal y colectiva, al llevar a cabo acciones de higiene, limpieza, y actividad física, desde los saberes prácticos de la comunidad y la información científica.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 60, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-007', 'Consumo de alimentos y bebidas que benefician la salud, de acuerdo con los contextos socioculturales.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 60, 'PLAN_2022_ED_2025_FASE_2', false),
  ('CONT-F2-HUM-008', 'Medidas de prevención de accidentes y situaciones de riesgo de acuerdo con el contexto, para el cuidado de la integridad personal y colectiva.', 'LO_HUMANO_LO_COMUNITARIO', 'FASE_2', 61, 'PLAN_2022_ED_2025_FASE_2', false)
insert into public.pda (codigo, texto, fuente_dof_pagina, fuente_dof_sha, grado, contenido_codigo, catalogo_version, activo, requiere_revision_humana) values
  ('PDA-F2-LNG-001-01', 'Emplea palabras, gestos, señas, imágenes, sonidos o movimientos corporales que aprende en su comunidad, para expresar necesidades, ideas, emociones y gustos que reflejan su forma de interpretar y actuar en el mundo.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-02', 'Reconoce que cuando juega y socializa con sus pares, se expresan desde sus posibilidades, vivencias y cultura.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-03', 'Espera su turno al participar en una conversación con sus compañeras o compañeros.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-04', 'Manifiesta oralmente y de manera clara necesidades, emociones, gustos, preferencias e ideas, que construye en la convivencia diaria, y se da a entender apoyándose de distintos lenguajes.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-05', 'Escucha con atención a sus pares y espera su turno para hablar.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-06', 'Se interesa por lo que otras personas expresan, sienten y saben e intercambia sus puntos de vista.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-07', 'De manera oral, expresa ideas completas sobre necesidades, vivencias, emociones, gustos, preferencias y saberes a distintas personas, combinando los lenguajes.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-08', 'Comprende, al interactuar con las demás personas, que existen diversas formas de comunicarse.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-001-09', 'Conversa y opina sobre diferentes temas y con varias personas interlocutoras.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-01', 'Evoca y narra fragmentos de diferentes textos literarios −leyendas, cuentos, fábulas, historias−, y relatos de la comunidad, que escucha en voz de otras personas que las narran o leen.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-02', 'Comparte las emociones que le provocan.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-03', 'Describe lugares o personajes de las historias o textos literarios que conoce y los relaciona con personas, paisajes y otros elementos de su comunidad.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-04', 'Explica lo que interpreta y entiende de las historias y textos literarios que conoce o escucha.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-05', 'Lee con apoyo y narra con una secuencia lógica, diferentes textos literarios como leyendas, cuentos, fábulas, historias, y relatos de la comunidad, en las que aprecia otras formas de vida, de pensamiento y de comportamiento.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-06', 'Narra con secuencia lógica, historias que conoce o inventa, y las acompaña con recursos de los lenguajes artísticos.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-07', 'Modifica eventos, lugares o personajes de distintas narraciones y textos literarios, utilizando recursos de los lenguajes que reflejan experiencias, emociones y vivencias propias relacionadas con su cultura.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-08', 'Narra historias que inventa considerando los momentos de inicio, desarrollo y final, de manera individual o colectiva.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-002-09', 'Describe detalles de personajes y lugares, los comparte con sus pares para evocarlos y enriquecerlos, e incorpora nuevos elementos a partir de los rasgos de su cultura y de otras regiones.', 20, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-01', 'Participa en juegos del lenguaje de la tradición oral de las familias o la comunidad y los expresa con fluidez.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-02', 'Combina recursos de los lenguajes, tales como movimientos corporales, gestos, velocidades, ritmos, entre otros, al decir rimas, poemas, canciones, retahílas, trabalenguas, adivinanzas y otros juegos del lenguaje.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-03', 'Descubre en los juegos del lenguaje, palabras nuevas y se interesa por saber su significado.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-04', 'Participa en juegos del lenguaje de la tradición oral de la comunidad o de otros lugares, los dice con fluidez, ritmo y claridad.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-05', 'Utiliza distintos recursos de los lenguajes, tales como sonido, ritmo, música, velocidad y movimientos corporales, gestos o señas, para acompañar y modificar adivinanzas, canciones, trabalenguas, retahílas, coplas, entre otros, y con ello crea otras formas de expresión.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-06', 'Interpreta el significado de palabras desconocidas en los juegos del lenguaje, a partir de su contexto.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-07', 'Propone y organiza con ayuda, juegos del lenguaje para invitar a sus pares a participar.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-08', 'Experimenta con los recursos de los lenguajes para crear, en lo individual y lo colectivo, juegos del lenguaje como adivinanzas, trabalenguas, canciones, rimas, coplas u otros.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-003-09', 'Combina e inventa nuevas palabras y las integra a su expresión.', 21, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-01', 'Reconoce que hay personas que se comunican en lenguas distintas a la propia.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-02', 'Identifica los distintos lenguajes que usan las personas a su alrededor.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-03', 'Se familiariza con lenguas distintas a la suya que escucha en su comunidad e incorpora a su comunicación, expresiones de origen indígena, extranjero o de las lenguas de señas.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-04', 'Muestra interés por indagar significados de palabras, frases o señas, y las incorpora a su comunicación como una forma de enriquecerla.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-05', 'Identifica y utiliza algunas palabras, frases o señas de la diversidad lingüística.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-06', 'Reconoce que algunos objetos se nombran de distinta manera, en diferentes regiones.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-07', 'Identifica que algunos nombres propios son de origen indígena y extranjero.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-004-08', 'Indaga, en distintas fuentes, el significado de términos o palabras que se utilizan en diferentes contextos o regiones.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-01', 'Explora y descubre diversos textos de su hogar y escuela, como cuentos, carteles, letreros o mensajes, e interpreta qué dicen a partir de las imágenes y marcas gráficas, e identifica para qué sirven.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-02', 'Relaciona el contenido de los diversos textos de su hogar y escuela con sus experiencias de vida.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-03', 'Interpreta, a partir de experiencias y referentes culturales, el contenido de diversos textos que le interesan y sabe para qué son.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-04', 'Representa gráficamente, con recursos personales, ideas y descubrimientos del entorno mediante textos conocidos.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-05', 'Comunica a diversas personas, mensajes con distintos propósitos.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-06', 'Comparte con sus pares los diversos textos de su interés, explica qué le gusta y por qué, e identifica su contenido.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-07', 'Utiliza distintos textos (carteles, avisos, periódico mural, revistas, hojas, cuadernos) para representar gráficamente ideas que descubre del entorno de manera vivencial y al consultar libros, revistas y otras fuentes impresas y digitales.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-08', 'Expresa sus preferencias hacia ciertos textos e identifica algunas de sus funciones, como obtener información y disfrutar historias, entre otras.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-005-09', 'Interpreta y elabora algunas señalizaciones, símbolos y letreros a partir de entender sus características, elementos gráficos y contexto.', 22, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-01', 'Representa emociones y experiencias de manera gráfica, haciendo uso de dibujos o recursos de los lenguajes artísticos.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-02', 'Presta atención a las producciones que comparten sus pares, y expresa lo que le provocan.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-03', 'Describe, en su producción gráfica: cómo se siente, por qué se siente así, lo que le provoca, o bien, relata lo que le sucedió.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-04', 'Elige algunos recursos gráficos, como marcas propias, símbolos, dibujos o algunos otros de los lenguajes artísticos, al representar emociones y experiencias.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-05', 'Observa las producciones de sus pares y expresa su opinión.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-06', 'Intercambia ideas acerca de las producciones de sus compañeras y compañeros, y encuentra semejanzas con las propias.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-07', 'Explica a otras personas lo que representan sus producciones gráficas (alguna emoción, experiencia, paisaje, ser vivo o persona).', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-08', 'Combina recursos gráficos y de los lenguajes artísticos, en la representación de emociones y experiencias.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-09', 'Explica y comparte sus producciones con las y los demás, dice o señala qué quiso representar y describe detalles para enfatizar ciertas emociones o experiencias.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-10', 'Argumenta su opinión acerca de las producciones de sus pares.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-11', 'Compara sus producciones con las de sus pares, para encontrar semejanzas en los elementos artísticos utilizados y en algunas emociones y experiencias.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-006-12', 'Reconoce que las demás personas tienen el mismo derecho para expresarse.', 23, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-01', 'Reconoce que las producciones gráficas, son una forma de establecer comunicación o vínculos con otras personas.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-02', 'Elabora producciones gráficas (mensajes, avisos, recados, entre otros) con marcas propias, dibujos o por medio del dictado, para informar algo a diferentes personas.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-03', 'Identifica su nombre escrito y otras palabras, en distintos objetos personales del aula o su casa.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-04', 'Encuentra semejanzas, ya sea por las grafías o los sonidos, con los nombres de sus pares.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-05', 'Reconoce que las producciones gráficas son importantes para mantener comunicación con su comunidad.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-06', 'Produce textos o mensajes de interés, con formas gráficas personales, copiando textos o dictando a alguien, con distintos propósitos y destinatarios.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-07', 'Representa su nombre y otras palabras comunes, con recursos propios y con distintos propósitos, tales como marcar sus producciones, registrar su asistencia, entre otros.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-08', 'Distingue semejanzas y diferencias con los nombres de sus pares, por los sonidos, marcas gráficas o letras.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-09', 'Planifica producciones gráficas, tales como avisos, recomendaciones de libros, recados, letreros, entre otros, de forma individual o en pequeños equipos.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-10', 'Recurre a diversos textos para copiar palabras, combinar letras del nombre propio, el de sus pares o dicta a alguna persona adulta, para establecer vínculos con las familias, la escuela y la comunidad.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-11', 'Usa grafías para representar su nombre y otras palabras conocidas con diversos propósitos.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-007-12', 'Reconoce las letras de su nombre en textos impresos y digitales.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-01', 'Describe características de manifestaciones culturales y artísticas de la comunidad, como los colores, texturas, tamaños, sonidos y posturas que reconoce, entre otros elementos.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-02', 'Comenta lo que le gusta, le provocan o le hacen sentir las manifestaciones artísticas o culturales de la comunidad (esculturas, pinturas, obras de teatro, entre otras).', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-03', 'Identifica emociones a partir de los elementos que componen las manifestaciones culturales y artísticas.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-04', 'Interpreta manifestaciones artísticas y culturales diversas (fotografías, música regional, murales, danzas, entre otras) a partir de los elementos que las componen.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-05', 'Interpreta manifestaciones artísticas y culturales diversas (fotografías, música regional, murales, danzas, entre otras) a partir de los elementos que las componen.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-06', 'Explica lo que le provocan las manifestaciones artísticas y culturales; y escucha lo que sus pares comparten.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-07', 'Comparte su experiencia estética con sus pares, al mencionar lo que le gusta, disgusta, lo que le provocan ciertos colores, formas, figuras, rostros, sonidos, posturas, entre otros elementos de las manifestaciones artísticas y culturales de su comunidad u otros lugares.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-08', 'Relaciona en las manifestaciones artísticas y culturales, sucesos, experiencias o emociones personales.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-09', 'Reconoce que existen opiniones diferentes en torno a la diversidad de manifestaciones artísticas y culturales.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-10', 'Explica lo que le gusta o disgusta, lo que se imagina y le provocan las manifestaciones culturales y artísticas (pinturas, zonas arqueológicas, poemas, artesanías, entre otras), a partir de sus elementos, como formas, trazos, personas, objetos o sonidos y ritmos.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-11', 'Aprecia y expresa gusto por ciertas manifestaciones o por alguna o algún artista.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-12', 'Relaciona en algunas manifestaciones artísticas y culturales, sucesos personales o familiares, así como lo que pasa en su comunidad.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-008-13', 'Escucha lo que le comparten sus pares y reconoce que hay diversidad de opiniones, gustos o disgustos alrededor de una misma manifestación artística o cultural.', 24, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-009-01', 'Experimenta con los diversos elementos de los lenguajes artísticos y descubre sus posibilidades de creación y expresión.', 26, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-009-02', 'Produce expresiones creativas para representar el mundo cercano, experiencias de su vida personal, familiar, la naturaleza que le rodea o creaciones de su imaginación, recurriendo a los distintos recursos de las artes.', 26, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-009-03', 'Muestra sensibilidad hacia las producciones de sus pares.', 26, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-LNG-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-009-04', 'Combina elementos de los lenguajes artísticos, tales como formas, colores, texturas, tamaños, líneas, sonidos, música, voces, entre otros, en producciones creativas, para representar el mundo cercano, experiencias personales, situaciones imaginarias o algún cuento.', 26, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-009-05', 'Aprecia con empatía las expresiones de otras personas.', 26, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-LNG-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-009-06', 'Enriquece sus producciones creativas de expresión gráfica o corporal, al incluir o retomar elementos, tales como líneas, combinación de colores, formas, imágenes, gestos, posturas, sonidos, entre otros, de las manifestaciones artísticas y culturales.', 26, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-LNG-009-07', 'Aprecia y opina sobre las creaciones de sus pares y otros artistas de la comunidad.', 26, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-LNG-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-01', 'Usa sus sentidos para percibir en su entorno cercano, plantas que le llaman la atención y describe características tales como: olor, color, forma, textura o tamaño, si tienen hojas, flores o frutos.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-02', 'Socializa lo que sabe sobre su entorno natural y hace nuevos descubrimientos con sus pares.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-03', 'Indaga sobre los cuidados que necesitan las plantas y los animales de su comunidad.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-04', 'Experimenta con elementos de la naturaleza para observar los cambios que ocurren y comunica a otros lo que sucedió.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-05', 'Observa y describe en su lengua materna, animales de su entorno: cómo son, cómo crecen, dónde viven, qué comen, los cuidados que necesitan y otros aspectos que le causan curiosidad.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-06', 'Amplía su conocimiento acerca de las plantas: su proceso de crecimiento, lo que necesitan para vivir, los lugares donde crecen, entre otros.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-07', 'Explica en su lengua materna y con sus palabras, cómo y por qué suceden algunos procesos naturales.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-08', 'Realiza experimentos para poner a prueba sus ideas y supuestos sobre lo que observa en su entorno.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-09', 'Consulta diferentes fuentes de información, digitales o impresas, para ampliar lo que sabe o intuye.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-10', 'Representa de manera gráfica lo que sabe de la naturaleza.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-11', 'Distingue algunas características del entorno natural: plantas, animales, cuerpos de agua, clima, entre otras.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-12', 'Se apoya en recursos impresos y digitales como fotografías, imágenes o videos para profundizar en sus conocimientos acerca de la diversidad de la naturaleza en su comunidad y otras regiones.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-13', 'Establece con sus pares, formas de organizar a los seres vivos y elementos de la naturaleza para establecer semejanzas y diferencias a la vez que aprecia su diversidad.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-14', 'Observa y experimenta con elementos de la naturaleza, comunica y registra sus hallazgos.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-001-15', 'Explica con sus palabras y en su lengua materna, procesos, fenómenos naturales y experimentos; los representa con recursos gráficos.', 32, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-01', 'Identifica saberes familiares que son útiles para la vida, sin poner en riesgo su integridad física y la de las otras personas.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-02', 'Comparte algunos saberes familiares con sus pares y descubre similitudes con los de otras familias.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-03', 'Se familiariza con historias, mitos y leyendas de la tradición oral de la comunidad que explican fenómenos de la naturaleza.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-04', 'Selecciona saberes familiares y comunitarios útiles, para resolver situaciones diversas, los compara con los de sus pares y cuida su integridad y la de los demás.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-05', 'Reconoce que los saberes familiares se comparten, modifican y enriquecen entre las personas de una comunidad.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-06', 'Explica en su lengua materna y con sus palabras, fenómenos naturales a partir de leyendas e historias de la comunidad, y con ayuda, los contrasta con otras fuentes de consulta.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-07', 'Propone algunos saberes familiares y comunitarios, para resolver necesidades y situaciones en su hogar, escuela y comunidad.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-08', 'Distingue, con ayuda de otras personas, situaciones en las que los saberes comunitarios son útiles y cuándo deben complementarse y/o contrastarse con otros conocimientos; cuidando su integridad y la de los demás.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-002-09', 'Indaga en distintas fuentes de consulta, incluyendo medios impresos y digitales, saberes y prácticas de otros lugares para cuidar la naturaleza.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-01', 'Hace preguntas sobre elementos de la naturaleza que le dan curiosidad, y las enriquece con las de sus pares.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-02', 'Examina el entorno natural con sus sentidos, de manera guiada, para resolver sus dudas y aprender cosas nuevas.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-03', 'Comparte sus descubrimientos, ideas y opiniones sobre los seres vivos, y escucha las de sus pares.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-04', 'Dice sus ideas acerca de cómo suceden y por qué ocurren algunos fenómenos naturales de su entorno: la lluvia, el arcoíris, la neblina o las olas, entre otros.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-05', 'Observa y nombra en su lengua materna las partes de su cuerpo, en situaciones cotidianas e intuye su funcionamiento.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-06', 'Hace preguntas sobre la naturaleza y, en colaboración con sus pares, pone a prueba ideas para encontrar respuestas que tengan sentido.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-07', 'Expresa en su lengua materna ideas acerca de por qué se producen algunos fenómenos naturales como el calor, el frío, un huracán o el rocío, e indaga en diferentes fuentes de consulta.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-08', 'Muestra interés sobre lo que sus pares saben acerca de fenómenos y procesos de la naturaleza, y reconoce que todas y todos pueden participar en la resolución de dudas.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-09', 'Describe los cambios físicos que percibe al crecer.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-10', 'Planifica de manera colaborativa indagaciones para ampliar sus conocimientos sobre la naturaleza, el planeta y el universo: hace preguntas, explora su entorno, expone sus ideas, busca información, compara lo que sabe, registra datos y explica sus hallazgos.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-11', 'Explica con sus palabras y en su lengua materna, la importancia del aire, el agua, el suelo y el sol para todos los seres vivos.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-12', 'Expresa lo que supone sucedería si se alteran las condiciones de la naturaleza por las acciones de las personas, por ejemplo, al contaminarla o dañarla.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-13', 'Explica con sus palabras cómo suceden y por qué se producen los fenómenos naturales de su entorno o de otros lugares: la actividad de un volcán, la nieve, una cascada, el granizo, un eclipse, entre otros.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-14', 'Se apoya de diversos recursos para ampliar lo que sabe.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-003-15', 'Indaga acerca de cómo funciona su cuerpo, sus cambios físicos, y explica lo que entiende.', 33, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-01', 'Reconoce números en su contexto sociocultural e interpreta su significado (saber la dirección de su casa, su peso o talla, hacer compras, entre otros).', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-02', 'Dice en su lengua materna, números en canciones o juegos.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-03', 'Usa números en juegos y situaciones cotidianas de su entorno.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-04', 'Interpreta situaciones numéricas que se le plantean y estima sus resultados.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-05', 'Cuenta objetos de su hogar y escuela con diferentes propósitos.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-06', 'Usa números con distintos propósitos y en distintas situaciones.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-07', 'Dice en orden los números que conoce y gradualmente amplía su rango de conteo.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-08', 'Cuenta objetos y elementos de su entorno.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-09', 'Compara colecciones de pocos elementos y las representa con dibujos o símbolos personales.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-10', 'Propone códigos personales para representar datos en forma gráfica.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-11', 'Resuelve de manera colaborativa situaciones sencillas que involucran números y que implican juntar, agregar, separar o quitar elementos.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-12', 'Se familiariza con el uso de monedas y billetes en diversas situaciones e intuye su valor.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-13', 'Intercambia con sus pares lo que ha aprendido sobre los números, para reconocer maneras más eficientes de usarlos en su entorno sociocultural en diversas situaciones.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-14', 'Dice la serie numérica en orden y amplía su rango de conteo.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-15', 'Cuenta objetos y elementos de su entorno en su lengua materna con diversos propósitos.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-16', 'Construye colecciones y las compara mediante distintas estrategias para determinar cuál tiene más o menos elementos.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-17', 'Representa cantidades, con dibujos, símbolos personales y numerales e interpreta los registros de sus pares.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-18', 'Construye y compara colecciones, usando distintas estrategias.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-19', 'Ordena elementos de una serie y usa números ordinales para expresar el lugar que ocupa cada elemento.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-20', 'Organiza y registra información en tablas o cuadros sencillos.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-21', 'Propone, de manera colaborativa, formas de resolver situaciones cotidianas e imaginarias que involucran acciones de agregar, juntar, quitar, separar, comparar e igualar cantidades.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-22', 'Reconoce el valor de monedas y billetes al usarlos en situaciones reales y de juego y estima para qué le alcanza.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-23', 'Intercambia con sus pares, saberes numéricos para plantear problemas y encontrar distintas estrategias para resolverlos de formas diversas y equitativas.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-004-24', 'Conoce formas de contar en otras culturas, como la maya, que usa rayas y puntos para representar los números.', 34, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-01', 'Usa el espacio inmediato al desplazarse y hacer recorridos en los que ubica, de manera intuitiva, la posición de objetos y personas.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-02', 'Reconoce algunas características del paisaje geográfico y usa referencias personales para ubicar elementos, objetos y lugares.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-03', 'Visualiza y describe con su propio lenguaje y en su lengua materna algunas características de forma en objetos cotidianos y las asocia con cuerpos geométricos.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-04', 'Reconoce patrones de repetición y crecimiento.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-05', 'Construye y reproduce objetos, figuras y escenarios (una torre, una casa, un monumento o un paisaje, entre otros) con bloques, materiales de arte y del entorno.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-06', 'Ubica personas, objetos y elementos de su entorno con referentes personales y los comunica a sus pares y otras personas.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-07', 'Establece relaciones de orientación y direccionalidad al interactuar y desplazarse en su entorno (hacia, desde, atrás, arriba, da vuelta).', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-08', 'Reconoce a partir de puntos de referencias personales de interioridad y proximidad, a las personas, objetos y elementos de su comunidad.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-09', 'Toma en cuenta que sus pares tienen otros referentes que debe considerar, ya que tienen otro punto de vista espacial.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-10', 'Reconoce semejanzas y diferencias entre las formas de los objetos de su entorno, explora y describe algunas características geométricas.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-11', 'Identifica formas geométricas en objetos de su entorno y los representa con dibujos y líneas.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-12', 'Distingue y reproduce patrones de repetición o crecimiento en una secuencia.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-13', 'Crea formas y composiciones geométricas con materiales de arte y construcción.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-14', 'Juega con el tangram para hacer composiciones y arma rompecabezas.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-15', 'Expresa la posición y ubicación de objetos, lugares y personas con respecto a su cuerpo y a otros objetos; usa gradualmente referentes convencionales.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-16', 'Interpreta y comunica en su lengua materna, recorridos y trayectorias con referentes espaciales de orientación y proximidad (cerca, lejos, arriba, abajo, delante, detrás, derecha, izquierda).', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-17', 'Planifica y dibuja recorridos, de su comunidad y de otros espacios, que contribuyen a reconocer el lugar donde vive.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-18', 'Observa y reconoce atributos geométricos en objetos y elementos de su entorno, y los describe con sus palabras y con términos convencionales.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-19', 'Representa y reproduce objetos, animales y plantas con el tangram, bloques de construcción, modelado, doblado de papel o con dibujos.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-20', 'Crea patrones de repetición y crecimiento para hacer secuencias.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-005-21', 'Imagina y anticipa los cambios que ocurrirán al manipular, apilar, rasgar y transformar objetos, haciendo composiciones geométricas.', 36, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-01', 'Compara “a ojo” y de manera perceptiva, la longitud de dos objetos y dice cuál es más largo o corto.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-02', 'Estima y expresa si un camino es más largo o corto que otro.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-03', 'Distingue objetos pesados y ligeros.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-04', 'Trasvasa líquidos con diferentes propósitos y se familiariza con lo que le cabe a un recipiente.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-05', 'Ordena actividades cotidianas y juegos que lleva a cabo en su casa y escuela, para identificar el paso del tiempo (desde que se levanta hasta que llega a la escuela o secuencias en los juegos).', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-06', 'Compara la longitud de dos o más objetos de uso cotidiano de manera directa o por superposición, contrasta sus ideas con sus pares.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-07', 'Estima si un lugar está más cerca o lejos que otro, y propone formas de medirlo para comprobarlo.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-08', 'Sopesa dos o más objetos para comparar su peso y dice cuál es más pesado o ligero que otro.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-09', 'Organiza actividades y juegos con sus pares, estableciendo una secuencia en su duración al llevarlas a cabo.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-10', 'Utiliza palabras relacionadas con el paso del tiempo que aprende en su contexto social, tales como: antes, después, primero, al final, temprano, en la mañana, en la tarde, en la noche, entre otras.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-11', 'Estima y compara la longitud de dos o más objetos con apoyo de un intermediario, y expresa cuál es más largo, más corto, más ancho, más angosto o si son iguales; con- trasta sus ideas con las de sus pares y las representa de manera gráfica.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-12', 'Mide objetos, áreas o distancias con unidades no convencionales que tiene al alcance y explica por qué son apropiadas; las representa de manera gráfica.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-13', 'Usa balanzas o básculas para comparar el peso de dos o más objetos.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-14', 'Trasvasa arena o líquidos entre recipientes de distintos tamaños y formas para medir su capacidad, y dice en cuál cabe más o menos.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-15', 'Percibe el paso del tiempo mediante eventos y procesos, con apoyo de la observación de cambios en la naturaleza, como el día y la noche, las estaciones del año, las temporadas de cosecha, el crecimiento de seres vivos o cualquier evento importante de la comunidad.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-006-16', 'Hace uso de instrumentos que miden el paso del tiempo, tales como calendarios, relojes de arena, solares, digitales y análogos.', 37, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-01', 'Identifica de manera intuitiva la forma en que se organizan los objetos en su hogar y escuela: lo que hay en la cocina, en la sala, en los estantes de su escuela, en el espacio escolar, entre otros.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-02', 'Explora las características de elementos y objetos de su entorno y establece con sus pares, semejanzas y diferencias; usa materiales del arte para representarlas.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-03', 'Observa y manipula objetos a su alcance para explorar sus características y experimentar con ellos, siguiendo normas de seguridad.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-04', 'Compara y organiza elementos del entorno, como objetos cotidianos o artesanías de su comunidad, de acuerdo con uno o dos criterios definidos con sus pares: color, forma, tamaño, textura o uso.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-05', 'Organiza por sus semejanzas, objetos y elementos de su entorno, con un propósito definido y los representa mediante dibujos, símbolos, pictogramas en cuadros y tablas sencillas.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-06', 'Mezcla o combina elementos de su entorno e identifica reacciones diversas, siguiendo normas de seguridad.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-07', 'Recolecta objetos y elementos de su entorno para observarlos, hacer preguntas y explorar sus características y comportamiento.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-08', 'Dialoga con sus pares para definir criterios de clasificación de objetos y elementos del entorno natural y sociocultural, que respondan a distintos propósitos.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-09', 'Elabora e interpreta registros para organizar objetos y elementos del entorno mediante dibujos, tablas, símbolos o pictogramas; los explica a otras personas, en su lengua materna y con sus palabras.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-10', 'Experimenta, de manera colaborativa, con elementos y objetos del entorno y reconoce si hay cambios o transformaciones en ellos, manteniendo normas de seguridad.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-007-11', 'Usa herramientas diversas en situaciones experimentales: lupas, microscopios, goteros, vasos medidores, balanzas, termómetro, lámparas, cernidores, entre otros.', 39, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-01', 'Observa y explora los materiales con los que están hechos los objetos, a través de juegos y actividades diversas.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-02', 'Reconoce en los objetos y elementos, algunas características de consistencia, forma, tamaño, color, textura o maleabilidad y si provienen de la naturaleza o los fabricó el ser humano.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-03', 'Escucha los sonidos que producen los objetos de su entorno y los reproduce con algunas partes del cuerpo u objetos.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-04', 'Percibe y describe cómo cambian los objetos y materiales de la naturaleza y de su entorno, al manipularlos o modificar sus condiciones, al modelar con masa, al observar cómo se derrite un helado si se deja al sol o cómo se mezclan los ingredientes para hacer un pastel.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-05', 'Explora las características de los materiales, para identificar su comportamiento al combinar los recursos artísticos, en actividades tales como modelar, construir, dibujar, colorear o pintar.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-06', 'Identifica otros usos que sus pares y las demás personas le dan a los objetos y materiales, en función de sus características y el contexto de uso.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-07', 'Identifica de dónde provienen algunos sonidos de su entorno y cuál es la fuente sonora, los imita y reproduce.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-08', 'Describe las características de los objetos y materiales de su entorno.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-09', 'Experimenta con distintos objetos para reconocer sus características y propiedades al manipularlos, combinarlos o transformarlos.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-10', 'Explica los resultados de sus experimentos y los contrasta con los hallazgos de sus pares, confirma o modifica sus suposiciones iniciales.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-11', 'Reconoce que las comunidades usan de diferente manera los objetos y materiales propios de su cultura: elaboran artesanías con papel, barro o arcilla, elaboran textiles, ropa y hacen bordados con diferentes materiales.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-12', 'Distingue los materiales de la naturaleza, de los fabricados por el ser humano.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-008-13', 'Experimenta con diversos objetos o instrumentos musicales, para producir y combinar diferentes sonidos.', 40, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-01', 'Usa en su vida diaria juguetes y artefactos tecnológicos que se encuentran en su hogar o escuela, observa cómo se usan: carritos, muñecos, tijeras, mecedoras, utensilios de cocina, entre otros.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-02', 'Plantea ideas acerca de cómo supone que funcionan los juguetes o artefactos tecnológicos.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-03', 'Encuentra formas creativas de usar juguetes, objetos y artefactos tecnológicos que tiene a su alcance.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-04', 'Observa y explica cómo entiende que funcionan los juguetes, objetos o artefactos tecnológicos del hogar, la escuela y la comunidad, por qué son útiles, y qué beneficios aportan a las personas y a la comunidad.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-05', 'Reconoce en su entorno sociocultural, diferentes usos que las personas le dan a los juguetes, objetos y artefactos tecnológicos, y comparte sus descubrimientos con sus pares para crear nuevas formas de usarlos.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-06', 'Indaga acerca del funcionamiento de juguetes, objetos y artefactos tecnológicos de distintos contextos y reconoce su beneficio.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-07', 'Imagina y propone con sus pares, nuevas formas de usar los objetos y artefactos tecnológicos para aprovecharlos de manera sustentable: usar una cuchara para comer, medir ingredientes o remover tierra para sembrar.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-SPC-009-08', 'Reconoce que las personas utilizan diferentes objetos o artefactos tecnológicos para desarrollar su oficio o profesión, en beneficio propio y de la comunidad.', 41, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-SPC-009', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-01', 'Convive con su entorno natural, con plantas y animales; expresa lo que percibe y disfruta acerca de ellos.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-02', 'Manifiesta actitudes de cuidado y empatía hacia los seres vivos y evita modificar sus condiciones naturales de vida al interactuar con ellos.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-03', 'Intuye que, al cuidar a la naturaleza, cuida de sí y de las demás personas.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-04', 'Identifica acciones que deterioran la naturaleza las evita, e invita a sus pares a cuidarla.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-05', 'Se relaciona con la naturaleza y considera la importancia de sus elementos para la vida (aire, sol, agua y suelo).', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-06', 'Aprecia la diversidad de características de los seres vivos y no vivos que hay en la naturaleza y sugiere formas de cuidarlos y preservarlos.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-07', 'Promueve actitudes y acciones de cuidado hacia la naturaleza e involucra a las personas de su familia y escuela para colaborar en ellas.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-08', 'Interactúa con respeto y empatía en la naturaleza, e identifica algunos elementos y cuidados que necesitan los seres vivos.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-09', 'Manifiesta interés por cuidar a la naturaleza y encuentra formas creativas de resolver problemas socioambientales de su comunidad, como la contaminación, la deforestación, el cambio climático, el deshielo o la sobreexplotación de los recursos naturales.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-001-10', 'Reconoce algunas condiciones ambientales de su comunidad y dice cómo afectan a plantas, animales y personas; en colaboración, hace propuestas para mejorarlas.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-01', 'Identifica objetos, prendas de vestir o alimentos que provienen de la naturaleza y los usa o consume de manera racional.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-02', 'Asocia los alimentos que consume, con los animales o plantas de los que provienen y evita el desperdicio.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-03', 'Relaciona las prendas de vestir con los materiales utilizados para su elaboración, tales como algodón, seda, cuero o piel, y cuida sus prendas.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-04', 'Cuida los bienes que provienen de la naturaleza al satisfacer necesidades y promueve que las demás personas también lo hagan.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-05', 'Observa que las personas transforman la naturaleza al interactuar con ella para satisfacer sus necesidades.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-06', 'Distingue acciones que son benéficas para su entorno, tales como sembrar y cuidar el crecimiento de las plantas, cuidar a los animales, respetar las reservas naturales, entre otras.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-07', 'Reconoce que todas las personas tienen necesidades básicas, como la alimentación, el vestido y la vivienda, y que estas se satisfacen con recursos de la naturaleza, como el agua simple potable para beber; frutas y verduras para comer, el algodón, la seda y el lino para hacer algunas prendas de ropa.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-08', 'Propone acciones para cuidar y preservar su entorno natural, como evitar el consumo de desechables y empaques no necesarios; el reciclado y reúso de materiales, el ahorro de agua y de energía eléctrica, entre otras.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-09', 'Promueve con la colaboración de las familias, el uso responsable de los recursos de la naturaleza al satisfacer necesidades de alimentación, vestido y vivienda.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-10', 'Asocia los recursos naturales de donde provienen algunos alimentos y explica con sus palabras, cómo cambia la naturaleza al obtenerlos y producirlos, así como al elaborar o fabricar prendas de vestir.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-11', 'Indaga los materiales con los que se construyen las viviendas y reconoce que se obtienen de la naturaleza.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-002-12', 'Sugiere y lleva a cabo algunas acciones sustentables a su alcance, para cuidar el ambiente natural y fomentar el buen vivir de las personas de la comunidad.', 46, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-01', 'Comparte con sus pares lo que entiende del significado de algunas celebraciones y conmemoraciones de su comunidad en las que participa o ha participado.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-02', 'Participa, disfruta y aprecia las celebraciones y eventos culturales y artísticos de su comunidad.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-03', 'Se interesa en elementos característicos de su comunidad, como la música, la danza, el baile o los objetos tradicionales.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-04', 'Construye de manera informal un sentido de pertenencia a su comunidad, al interpretar el significado de sus celebraciones y conmemoraciones.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-05', 'Intercambia con sus pares, experiencias y vivencias al participar en eventos, celebraciones y conmemoraciones de su comunidad, y las representa con recursos artísticos.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-06', 'Reconoce que los eventos, celebraciones y conmemoraciones son parte de la historia de su comunidad y país.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-07', 'Conoce y disfruta lugares de relevancia natural, cultural e histórica de su comunidad y país, como monumentos, zonas arqueológicas, áreas naturales protegidas, museos o casas de cultura.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-08', 'Explica con sus propias palabras, lo que siente y disfruta acerca de las tradiciones, celebraciones y elementos culturales y artísticos de su comunidad.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-09', 'Aprecia la riqueza de la historia de su comunidad a través de relatos, historias, leyendas, mitos, conmemoraciones, celebraciones tradicionales, obras culturales y artísticas.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-10', 'Se interesa, junto con sus pares, por conocer la diversidad cultural y artística de otras regiones del país, así como otras costumbres y tradiciones que enriquecen su visión del país y del mundo.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-11', 'Entiende que los símbolos patrios representan los valores y la historia de México y los explica con sus propias palabras; reconoce los lugares y momentos apropiados para usarlos.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-003-12', 'Reconoce que algunas tradiciones surgen de situaciones, eventos o vivencias comunitarias relevantes y que se modifican con el paso del tiempo.', 48, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-004-01', 'Recuerda y comparte acontecimientos importantes en su historia personal con apoyo de fotografías, objetos y narraciones de integrantes de su familia, y se percata de cómo ha cambiado.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-004-02', 'Observa las similitudes y diferencias entre los sucesos importantes de las distintas familias en la convivencia diaria, como cumpleaños, celebraciones o eventos.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-004-03', 'Evoca, con apoyo de sus familiares, acontecimientos y sucesos personales relevantes de su historia de vida y los comparte con sus pares, mediante narraciones y fotografías.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-004-04', 'Se da cuenta de que al pasar el tiempo se producen cambios en sus rasgos físicos, en los lugares que frecuenta, en los objetos y en las costumbres de las distintas familias y de la comunidad.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-004-05', 'Identifica, con ayuda, y a través de narraciones, cartas, fotografías, objetos, ropa y otros elementos, acontecimientos y sucesos importantes ocurridos en su familia a lo largo del tiempo.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-004-06', 'Comprende que, con el paso del tiempo, se modifican los paisajes, los objetos, las costumbres y las formas de vida de la comunidad, por lo que se debe actuar con responsabilidad para el bienestar individual y colectivo.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-005-01', 'Observa y conoce las labores y actividades que desarrollan los integrantes de su familia, e identifica que tienen un impacto en la comunidad.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-005-02', 'Conoce a través de sus pares, las labores y actividades que desarrollan los integrantes de otras familias.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-005-03', 'Se involucra gradualmente en las labores de su hogar y escuela en condiciones de equidad y se da cuenta de los beneficios que aporta.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-005-04', 'Identifica que las personas realizan actividades diversas y ofrecen distintos servicios que contribuyen a lograr metas comunes.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-005-05', 'Comparte con sus pares la importancia de los trabajos y servicios que las y los integrantes de las familias desarrollan en sus hogares y la comunidad, en condiciones de igualdad y equidad.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-005-06', 'Aprecia las labores y servicios que existen en la comunidad y valora el impacto que tienen para el bienestar común.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-005-07', 'Utiliza lo que sabe de los trabajos y servicios que existen en su comunidad, para proponer nuevas formas de colaborar y contribuir al bienestar de todas las personas.', 49, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-01', 'Se familiariza con algunos de sus derechos, como vivir en una familia, derecho a la protección, a la salud, a jugar, a tener un nombre, una vivienda y acudir a la escuela, los cuales se manifiestan en situaciones cotidianas de su vida.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-02', 'Reconoce algunos de sus derechos en voz de las personas adultas que le rodean y que garantizan su ejercicio, para todas las niñas y todos los niños sin distinción.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-03', 'Expresa dudas acerca del significado de algunos de sus derechos a personas adultas, y los relaciona con situaciones cotidianas.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-04', 'Identifica algunas situaciones en las que sus derechos y los de otras niñas y otros niños, no son respetados.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-05', 'Expresa lo que entiende acerca de los derechos de niñas y niños, dice cómo los vive y disfruta en situaciones cotidianas, y escucha cómo lo hacen sus pares.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-06', 'Reconoce que todas las niñas y todos los niños tienen derechos, sin importar su origen étnico, condición, color de piel, género, edad, discapacidad o lengua y que deben respetarse en cualquier contexto y lugar.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-07', 'Establece acuerdos con sus pares y otras personas para mejorar la convivencia en beneficio común.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-08', 'Explica con sus palabras y mediante otros lenguajes, lo que entiende de cada uno de los derechos de niñas y niños, y escucha las opiniones de sus pares.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-09', 'Difunde los derechos de las niñas y los niños en su escuela y entorno cercano, para favorecer que todas las personas los respeten y contribuyan a su ejercicio.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-006-10', 'Reconoce que una convivencia pacífica se basa en el respeto de los derechos de todas y todos.', 50, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-007-01', 'Comparte con sus pares información personal acerca de sus gustos, familia, emociones, identidad, entre otros.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-007-02', 'Reconoce que es diferente a las y los demás y que esas diferencias enriquecen la convivencia.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-007-03', 'Expresa algunas de sus costumbres y rutinas familiares, y las compara con las de sus pares, encontrando similitudes.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-007-04', 'Se da cuenta de que las familias son diversas y distintas entre sí, y que esto favorece la convivencia en un entorno de inclusión y respeto.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-007-05', 'Reconoce las distintas formas de ser y actuar de sus pares, para convivir en armonía.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-007-06', 'Conversa con sus pares acerca de lo que significa pertenecer a una familia, los cuidados que reciben, las reglas que deben seguir, algunas de sus costumbres, y reconoce que se conforman de diferente manera, sin que una tenga más valor que otra.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-008-01', 'Establece acuerdos de convivencia en su salón y escuela para desenvolverse en un ambiente seguro y respetuoso.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-008-02', 'Conversa con sus pares acerca de lo que para ella o él significa la paz, y nutre su concepción a partir de ello.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-008-03', 'Colabora con la cultura de paz en su hogar y escuela, al convivir de manera respetuosa y armónica.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-ENS-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-008-04', 'Construye acuerdos para una convivencia pacífica en su hogar y escuela, al escuchar y expresar con respeto ideas y opiniones propias y de las demás personas, que fortalezcan una cultura de paz.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-008-05', 'Acuerda con su familia, pares y otras personas, las responsabilidades que tendrá en su hogar y escuela, y explica por qué es importante cumplirlas.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-ENS-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-008-06', 'Se expresa y participa con libertad y respeto en diversas situaciones y contextos, favoreciendo una cultura de paz y la convivencia pacífica en un marco de inclusión y diversidad.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-ENS-008-07', 'Reconoce los desacuerdos como oportunidades para construir un ambiente de equidad e inclusión.', 51, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-ENS-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-01', 'Descubre gustos, preferencias, posibilidades motrices y afectivas, en juegos y actividades que contribuyan al conocimiento de sí, en un ambiente que considere la diversidad.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-02', 'Describe cómo es físicamente, identifica sus rasgos familiares y se acepta como es.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-03', 'Representa la imagen que tiene de sí, a través del modelado, dibujo, pintura y otros recursos de los lenguajes artísticos, y respeta las producciones de sus pares.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-04', 'Reconoce algunos rasgos de su identidad, dice cómo es físicamente, qué se le facilita, qué se le dificulta, qué le gusta, qué no le gusta, y los expresa en su lengua materna o con otros lenguajes.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-05', 'Distingue semejanzas y diferencias con las demás personas, a partir de distintos rasgos de identidad como su nombre, características físicas, formas de vestir, hablar, alimentarse, entre otros.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-06', 'Identifica que todas y todos pertenecen a familias que son diversas y muestra respeto a las formas de ser, de pensar y de relacionarse con las y los demás.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-07', 'Representa la imagen que tiene de sí y de sus pares con apoyo de diversos recursos de los lenguajes artísticos.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-08', 'Identifica que la lengua que habla, las costumbres familiares y el lugar donde vive contribuyen a la formación de su identidad y pertenencia a una comunidad en la que participa y colabora.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-09', 'Aprecia las características y cualidades propias, así como las de sus pares y de otras personas.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-10', 'Muestra seguridad y confianza en sus formas de ser, actuar, pensar e interactuar en la casa, escuela y comunidad.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-001-11', 'Expresa y representa con recursos de los distintos lenguajes, la imagen que tiene de sí y de las y los demás.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-001', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-01', 'Explora las posibilidades de movimiento de su cuerpo, en juegos y actividades, de acuerdo con las características y condiciones personales.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-02', 'Imita y descubre movimientos y posturas, involucrando distintos segmentos corporales que favorecen el control y la lateralidad.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-03', 'Describe las sensaciones que percibe en su cuerpo al realizar movimientos o mantener ciertas posturas.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-04', 'Adapta sus movimientos y fortalece su lateralidad al desplazarse en espacios de la escuela, casa y comunidad en distintas direcciones y con velocidades variadas; descubre nuevas formas de moverse.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-05', 'Mantiene el control y equilibrio de los distintos segmentos corporales tanto en situaciones estáticas (sostenerse en un pie, hacer una figura con el cuerpo, entre otras) como en movimientos sin desplazamiento (girar, brincar, etcétera).', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-06', 'Explica los cambios que experimenta su cuerpo cuando realiza actividad física, y con ayuda, reconoce señales de dolor o malestar.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-07', 'Combina movimientos que implican el control, equilibrio y estabilidad del cuerpo al realizar acciones individuales, en parejas o en colectivo.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-08', 'Incorpora en sus movimientos elementos de la estructura del espacio físico como la distancia, la dirección, la temporalidad, la velocidad, la posición y la lateralidad.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-09', 'Coordina movimientos con control y equilibrio al resolver situaciones cotidianas, participar en juegos tradicionales y representaciones individuales o colectivas en igualdad de oportunidades y sin distinción de género.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-002-10', 'Reconoce cuando realiza un sobreesfuerzo físico: dolor torácico, mareos, deshidratación o dificultad para respirar; pone en práctica estrategias que le ayudan a recuperar un estado de bienestar.', 56, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-002', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-01', 'Explora y manipula objetos, herramientas y materiales de distintas formas, texturas y tamaños.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-02', 'Participa en juegos y actividades que involucran la coordinación de movimientos, usando los sentidos, en acciones como lanzar, amasar, patear, entre otras.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-03', 'Usa objetos, herramientas y materiales pertinentes que le ayudan a resolver situaciones específicas y cotidianas en casa y escuela.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-04', 'Controla sus movimientos al usar objetos, herramientas y materiales en juegos y actividades de experimentación, creación personal y resolución de problemas, atendiendo las normas de seguridad.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-05', 'Descubre nuevas formas de coordinar sus movimientos al transportar objetos con alguna parte del cuerpo, caminar y lanzar una pelota, alternar el uso de manos y pies, entre otros.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-06', 'Controla cada vez con mayor precisión sus movimientos en coordinación con sus sentidos, al jugar y realizar actividades.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-07', 'Resuelve situaciones cotidianas mediante el uso de objetos, herramientas y materiales que implican el control y precisión de movimientos para satisfacer necesidades personales y colectivas.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-08', 'Construye y modela objetos, con control y precisión de sus movimientos; selecciona objetos, herramientas y materiales apropiados para resolver situaciones diversas.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-003-09', 'Respeta y pone en práctica, medidas de seguridad al manipular objetos, herramientas y materiales en diferentes lugares.', 57, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-003', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-01', 'Identifica emociones como alegría, tristeza, sorpresa, miedo o enojo, al participar en juegos de representación.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-02', 'Expresa lo que siente o le provocan algunas situaciones, seres vivos o personas con las que interactúa en su vida cotidiana, usando diferentes recursos de los lenguajes.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-03', 'Escucha con empatía a sus pares, cuando hablan acerca de personas que les generan confianza o incomodidad, y de situaciones o seres vivos que les provocan agrado o desagrado.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-04', 'Reconoce o se percata cuando sus pares necesitan ayuda para recuperar la calma o mantener un estado de bienestar, y ofrece su apoyo.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-05', 'Percibe cambios corporales, y con ayuda, nombra las emociones que experimenta, como: alegría, tristeza, sorpresa, miedo o enojo, y reconoce las situaciones que las provocan.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-06', 'Manifiesta a una persona adulta, de manera verbal o con otros lenguajes, si alguien le hace sentir incomodidad, le provoca miedo o inseguridad.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-07', 'Indaga algunas medidas para aprender a pedir ayuda y ponerse a salvo, como gritar, correr, recurrir a una persona de confianza, entre otras.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-08', 'Muestra respeto y empatía hacia la expresión de emo- ciones de las personas, comprende cuando alguien necesita ayuda y la ofrece.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-09', 'Establece vínculos afectivos y de empatía con sus pares y otras personas, a partir de la convivencia cotidiana.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-10', 'Intercambia experiencias y vivencias con sus pares y otras personas, acerca de las diferentes formas de actuar, expresar, nombrar y controlar las emociones.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-11', 'Dice lo que le molesta o incomoda para evitar reaccionar con gritos o agresión; dialoga y respeta las reglas para una mejor convivencia.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-12', 'Identifica situaciones en las que percibe que está en riesgo su integridad o la de otras personas.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-004-13', 'Conversa con sus pares acerca de lo que hacen para enfrentar situaciones de riesgo y buscan distintas alternativas para sentir seguridad y ponerse a salvo.', 58, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-004', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-01', 'Interactúa con diferentes compañeras y compañeros, para establecer relaciones de amistad, igualdad, empatía y colaboración.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-02', 'Identifica las consecuencias positivas o negativas de sus comportamientos ante distintas situaciones y fomenta con sus pares, aquellos que promueven una sana y positiva convivencia.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-03', 'Participa y respeta acuerdos de convivencia en juegos y actividades que implican compartir materiales, establecer turnos, seguir reglas, escuchar con atención, entre otros.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-04', 'Interactúa con distintas personas en situaciones diversas, y establecen acuerdos para la participación, la organización y la convivencia.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-05', 'Se relaciona con respeto y colabora de manera asertiva para el logro de propósitos comunes en juegos y actividades.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-06', 'Manifiesta disposición para establecer acuerdos que beneficien a todas y todos a fin de convivir con respeto y tolerancia a las diferencias.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-07', 'Conoce distintas alternativas para colaborar con la comunidad e integrarse a ella, de acuerdo con sus condiciones.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-08', 'Propone y lleva a cabo formas de convivencia libres de violencia en la casa, escuela y comunidad.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-09', 'Se integra con seguridad y confianza en actividades colectivas al interactuar con personas de otros lugares y culturas.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-005-10', 'Asume actitudes prosociales como compartir, ayudar y colaborar, al participar y mejorar las relaciones de convivencia con las demás personas.', 59, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-005', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-01', 'Practica hábitos de higiene personal y limpieza en los espacios físicos donde se desenvuelve y al usar objetos, como medidas de conservación de la salud y de prevención de enfermedades.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-02', 'Reconoce los beneficios que la actividad física, la alimentación y los hábitos de higiene personal y limpieza aportan al cuidado de la salud.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-03', 'Consulta, con ayuda, y dialoga con personas de la comunidad o especialistas en el cuidado de la salud infantil, las medidas de prevención de enfermedades y conservación de la salud.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-04', 'Se familiariza con diversas prácticas que favorecen el cuidado de la salud desde la experiencia y visión de otras culturas, sin ponerse en riesgo.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-05', 'Busca con ayuda, información en diversas fuentes científicas acerca de las acciones que están a su alcance, para el cuidado de la salud personal y colectiva, y las pone en práctica.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-06', 'Realiza acciones de higiene personal y limpieza, antes, durante y después de realizar sus actividades cotidianas.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-07', 'Disfruta de realizar actividades físicas y reconoce los beneficios para su salud.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-08', 'Sabe a dónde o con quién acudir para mantener su salud o cuando tiene algún malestar físico o enfermedad.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-09', 'Reconoce algunos factores que permiten conservar la salud y los que la perjudican.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-10', 'Propone acciones que contribuyen a mantener su salud y bienestar, relacionadas con higiene personal, limpieza y actividad física, considerando los saberes prácticos de la comunidad y las aportaciones científicas.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-11', 'Promueve acciones sobre el cuidado de la salud visual, auditiva, bucal, alimentaria y física, en la casa, escuela y comunidad.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-006-12', 'Dialoga con sus pares y toman acuerdos para el cuidado de la salud en beneficio de todas y todos.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-006', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-01', 'Expresa gustos y preferencias de bebidas y alimentos que hay en su comunidad, al explorar aromas, colores, texturas y sabores, guardando medidas de seguridad e higiene.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-02', 'Reconoce, en las costumbres familiares, la preparación y consumo de alimentos y bebidas, e identifica los que son saludables y los que ponen en riesgo la salud.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-03', 'Practica hábitos de higiene y limpieza en el consumo y preparación de alimentos y bebidas.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-04', 'Distingue alimentos y bebidas que son saludables, así como los que ponen en riesgo la salud, y reconoce que existen opciones alimentarias sanas que contribuyen a una mejor calidad de vida para todas las personas.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-05', 'Indaga acerca de la comida tradicional de su comunidad y otras regiones, y aprecia la diversidad de alimentos y platillos saludables que se consumen en el país.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-06', 'Cuida su salud al llevar a cabo medidas de seguridad, higiene y limpieza, en la preparación y consumo de alimentos y bebidas saludables.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-07', 'Obtiene información de diversas fuentes, acerca de los factores que favorecen estilos de vida saludable, destacando el consumo de alimentos nutritivos y de agua simple potable, entre otros.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-08', 'Aprecia la cultura alimentaria mexicana, y descubre la diversidad de ingredientes que existen en el país, así como la influencia de otras culturas en el consumo y preparación de alimentos.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-007-09', 'Promueve el consumo de alimentos sanos propios de su comunidad y la creación de huertos para la siembra y cosecha de frutas y verduras.', 60, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-007', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-01', 'Explora los espacios físicos de su casa, escuela y comunidad para identificar las zonas de seguridad que le permitan mantener su integridad en caso de situaciones de riesgo.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-02', 'Identifica acciones, situaciones y comportamientos en los que puede lastimarse o lastimar a las demás personas.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-03', 'Comparte con sus pares ideas acerca de cómo cuidar su integridad y la de las demás personas, y con ayuda, las pone en práctica.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-04', 'Propone de manera colaborativa y lleva a cabo, acuerdos que contribuyen a evitar accidentes o lesiones al manipular objetos y materiales, así como a usar con seguridad los espacios de juego y actividades en casa, escuela y comunidad.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '1°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-05', 'Expresa qué comportamientos, objetos, materiales y lugares pueden provocar accidentes y poner en riesgo la seguridad y el bienestar personal y colectivo.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-06', 'Lleva a cabo acciones para prevenir accidentes y salvaguardar su bienestar y seguridad, personales y colectivos.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-07', 'Reconoce las situaciones de riesgo provocadas por fenómenos naturales o por la acción humana, y sabe qué hacer y cómo reaccionar para salvaguardar su integridad.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-08', 'Atiende medidas de seguridad para aprender cómo actuar antes, durante y después de una emergencia y cuidar su integridad y la de las demás personas.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '2°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-09', 'Indaga en diferentes fuentes de consulta y con expertos, acerca de los posibles riesgos y daños que provocan algunos fenómenos naturales como: sismos, inundaciones, huracanes, entre otros.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-10', 'Propone y lleva a cabo, acciones de seguridad y formas de colaboración en situaciones de riesgo, accidentes o desastres, tomando en cuenta el bienestar de las personas y otros seres vivos de la comunidad.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false),
  ('PDA-F2-HUM-008-11', 'Colabora en acciones de difusión, al promover una cultura de prevención de accidentes y ries- gos para el beneficio común.', 61, 'f981c30ea9619f5841f4729a6f697951e035eff78c1e1042d02d0d5d663c8702', '3°', 'CONT-F2-HUM-008', 'PLAN_2022_ED_2025_FASE_2', true, false)
