-- 0026_catalogo_completo_fase2.sql
-- Catálogo oficial completo de la Fase 2 (Preescolar) - Plan de Estudio 2022 NEM
-- Contenidos (34) y Procesos de Desarrollo de Aprendizaje (375) para 1°, 2° y 3° grado de preescolar.
-- Fuente oficial: Programa Sintético Fase 2 (80 páginas SEP).

-- 1. Contenidos oficiales Fase 2 (34)
on conflict (codigo) do update set
  texto = excluded.texto,
  campo_codigo = excluded.campo_codigo,
  fase_codigo = excluded.fase_codigo,
  fuente_dof_pagina = excluded.fuente_dof_pagina;

-- 2. Procesos de Desarrollo de Aprendizaje (PDA) Fase 2 (375)
on conflict (codigo) do update set
  texto = excluded.texto,
  fuente_dof_pagina = excluded.fuente_dof_pagina,
  grado = excluded.grado,
  contenido_codigo = excluded.contenido_codigo,
  activo = excluded.activo;

-- 3. Relación PDA por campo formativo y fase
on conflict (pda_codigo, fase_codigo, campo_codigo) do nothing;
